1	using System.Collections.Generic;
2	using System.Linq;
3	using DefaultEcs;
4	using DefaultEcs.System;
5	using Microsoft.Xna.Framework;
6	using Microsoft.Xna.Framework.Graphics;
7	using MonoDreams.Component;
8	using MonoDreams.Component.Draw;
9	using MonoDreams.State;
10	using MonoGame.Extended.BitmapFonts;
11	
12	namespace MonoDreams.System.Draw;
13	
14	/// <summary>
15	/// Unified rendering system that handles all draw types: sprites, text, nine-patch, and mesh.
16	/// This system is game-agnostic — it only renders what's in DrawComponent without any
17	/// specialized component handling.
18	/// <para>
19	/// One instance renders a single pass: every entity whose <see cref="DrawComponent.Target"/>
20	/// equals <paramref name="source"/>, through the optional <paramref name="camera"/> view
21	/// transform (null ⇒ screen-space, no transform), into <paramref name="destination"/>.
22	/// Compose multiple instances for multiple views — e.g. the world (Main) through the main
23	/// camera, plus UI and HUD screen-space passes, plus a minimap (Main through a second camera
24	/// into its own target), splitscreen, CCTV, or portal textures. The instances are independent
25	/// render passes; <see cref="FinalDrawSystem"/> arranges their targets onto the screen.
26	/// </para>
27	/// </summary>
28	public class MasterRenderSystem(
29	    SpriteBatch spriteBatch,
30	    GraphicsDevice graphicsDevice,
31	    World world,
32	    RenderTargetID source,
33	    RenderTarget2D destination,
34	    MonoDreams.Component.Camera? camera = null,
35	    SamplerState? spriteSampler = null,
36	    SamplerState? textSampler = null) : ISystem<GameState>
37	{
38	    /// <summary>
39	    /// The render target this pass draws into. Mutable so a pass whose target tracks the window
40	    /// size (e.g. the editor's native-resolution chrome target) can be retargeted after a resize
41	    /// recreates the target — the mesh projection re-derives from the current destination size on
42	    /// every draw, so retargeting needs no other bookkeeping. The pass does NOT own/dispose the
43	    /// target (the screen or the retargeting owner does).
44	    /// </summary>
45	    public RenderTarget2D Destination { get; set; } = destination;
46	
47	    private BasicEffect? _basicEffect;
48	
49	    // A 1×1 white pixel used to stroke text underlines in the text branch (tinted with the text
50	    // color). Created lazily on the graphics device, disposed with the system.
51	    private Texture2D? _pixel;
52	
53	    // The draw set for this pass, built once and reused for the system's lifetime.
54	    // AsSet() registers subscriptions the World keeps alive forever — building a fresh
55	    // set every frame leaks an EntitySet + its subscriptions per frame, so memory climbs
56	    // even on a static scene. See premise "Per-target draw sets are built once, not per frame".
57	    private EntitySet? _drawSet;
58	
59	    private EntitySet DrawSet => _drawSet ??= BuildDrawSet();
60	
61	    private EntitySet BuildDrawSet()
62	    {
63	        var queryBuilder = world.GetEntities()
64	            .With((in DrawComponent e) => e.Target == source);
65	
66	        // The world (Main) respects CullingSystem visibility; screen-space passes always render.
67	        if (source == RenderTargetID.Main)
68	            queryBuilder = queryBuilder.With<VisibleComponent>();
69	
70	        return queryBuilder.AsSet();
71	    }
72	
73	    // Pixel art wants nearest-neighbour for sprites (and meshes); downscaled bitmap fonts
74	    // read better with linear filtering — so each draw type gets its own sampler. Both are
75	    // overridable per game; the defaults suit this engine's pixel-art content.
76	    private SamplerState SpriteSamplerState => spriteSampler ?? SamplerState.PointClamp;
77	    private SamplerState TextSamplerState => textSampler ?? SamplerState.LinearClamp;
78	
79	    private enum BatchType { None, Sprite, Text, Mesh }
80	
81	    private static BatchType GetBatchType(DrawElementType type) => type switch
82	    {
83	        DrawElementType.Mesh => BatchType.Mesh,
84	        DrawElementType.Text => BatchType.Text,
85	        _ => BatchType.Sprite,
86	    };
87	
88	    // The mesh ortho projection maps this destination's pixel space to NDC. Derived from the
89	    // destination size (not the camera) so screen-space passes need no camera; the camera's
90	    // virtual resolution must match the destination size (it centers the view there).
91	    private Matrix Projection() =>
92	        Matrix.CreateOrthographicOffCenter(0, Destination.Width, Destination.Height, 0, 0, 1);
93	
94	    private Texture2D Pixel()
95	    {
96	        if (_pixel == null)
97	        {
98	            _pixel = new Texture2D(graphicsDevice, 1, 1);
99	            _pixel.SetData(new[] { Color.White });
100	        }
101	        return _pixel;
102	    }
103	
104	    private void EnsureBasicEffect()
105	    {
106	        _basicEffect ??= new BasicEffect(graphicsDevice)
107	        {
108	            VertexColorEnabled = true,
109	            View = Matrix.Identity,
110	            Projection = Projection(),
111	        };
112	    }
113	
114	    private void BeginSpriteBatch(Matrix transformMatrix, SamplerState samplerState)
115	    {
116	        spriteBatch.Begin(
117	            sortMode: SpriteSortMode.Deferred, // We pre-sort, so no need for FrontToBack
118	            blendState: BlendState.AlphaBlend,
119	            samplerState: samplerState,
120	            depthStencilState: DepthStencilState.None,
121	            rasterizerState: RasterizerState.CullNone,
122	            effect: null,
123	            transformMatrix: transformMatrix);
124	    }
125	
126	    private void EndSpriteBatch() => spriteBatch.End();
127	
128	    private void ResetGraphicsStateForMeshRendering()
129	    {
130	        // Reset states after SpriteBatch.End() before mesh rendering
131	        graphicsDevice.BlendState = BlendState.AlphaBlend;
132	        graphicsDevice.DepthStencilState = DepthStencilState.None;
133	        graphicsDevice.RasterizerState = RasterizerState.CullNone;
134	        graphicsDevice.SamplerStates[0] = SamplerState.PointClamp;
135	    }
136	
137	    public void Update(GameState state)
138	    {
139	        EnsureBasicEffect();
140	
141	        graphicsDevice.SetRenderTarget(Destination);
142	        graphicsDevice.Clear(Color.Transparent);
143	
144	        var transformMatrix = camera?.GetViewTransformationMatrix() ?? Matrix.Identity;
145	
146	        // Sort ALL entities by LayerDepth (stable sort preserves order for same depth)
147	        var entities = DrawSet.GetEntities().ToArray();
148	        var sortedEntities = entities
149	            .Select((entity, index) => (entity, index, dc: entity.Get<DrawComponent>()))
150	            .Where(x => x.dc.Type != DrawElementType.Mesh || x.dc.HasValidMesh)
151	            .OrderBy(x => x.dc.LayerDepth)
152	            .ThenBy(x => x.index) // Stable sort
153	            .ToList();
154	
155	        if (sortedEntities.Count > 0)
156	            RenderInterleaved(sortedEntities, transformMatrix);
157	    }
158	
159	    private void RenderInterleaved(
160	        List<(Entity entity, int index, DrawComponent dc)> sortedEntities,
161	        Matrix transformMatrix)
162	    {
163	        BatchType currentBatch = BatchType.None;
164	        // The running quad count + flush decision for the *current* SpriteBatch Begin/End run, shared with
165	        // the SpriteBatchFlushTests so the renderer and its tests exercise the same flush logic. Reset on
166	        // every Begin (context switch or flush); used to keep each run below the Reach 16-bit-index budget.
167	        var batchRun = new SpriteBatchFlush.BatchRun();
168	
169	        foreach (var (_, _, dc) in sortedEntities)
170	        {
171	            var requiredBatch = GetBatchType(dc.Type);
172	
173	            // Batch type changed - switch context. Sprite and Text both use the SpriteBatch
174	            // but with different samplers, so switching between them flushes + reopens it.
175	            // Painter's order is preserved because the list is already depth-sorted.
176	            if (requiredBatch != currentBatch)
177	            {
178	                // End previous batch
179	                if (currentBatch is BatchType.Sprite or BatchType.Text)
180	                    EndSpriteBatch();
181	
182	                // Start new batch
183	                if (requiredBatch == BatchType.Sprite)
184	                {
185	                    BeginSpriteBatch(transformMatrix, SpriteSamplerState);
186	                    batchRun.Reset();
187	                }
188	                else if (requiredBatch == BatchType.Text)
189	                {
190	                    BeginSpriteBatch(transformMatrix, TextSamplerState);
191	                    batchRun.Reset();
192	                }
193	                else if (requiredBatch == BatchType.Mesh)
194	                    ResetGraphicsStateForMeshRendering();
195	
196	                currentBatch = requiredBatch;
197	            }
198	
199	            // Draw the element. Sprite/Text both accumulate into the current Begin/End run via the same
200	            // BatchRun the tests drive: ConsumeBefore decides whether the run must flush (End + reopen
201	            // with the same sampler) before this element to stay below the Reach 16-bit-index cap, and
202	            // folds the element's quad count into the run. Called once per sprite/text element — including
203	            // the first after a context switch (its count is 0, so it never flushes).
204	            if (requiredBatch == BatchType.Mesh)
205	                DrawSingleMesh(dc, transformMatrix);
206	            else
207	            {
208	                if (batchRun.ConsumeBefore(dc))
209	                {
210	                    EndSpriteBatch();
211	                    BeginSpriteBatch(
212	                        transformMatrix,
213	                        currentBatch == BatchType.Text ? TextSamplerState : SpriteSamplerState);
214	                }
215	                DrawElement(dc); // Sprite or Text
216	            }
217	        }
218	
219	        // End final batch if it was a SpriteBatch one
220	        if (currentBatch is BatchType.Sprite or BatchType.Text)
221	            EndSpriteBatch();
222	    }
223	
224	    private void DrawSingleMesh(DrawComponent dc, Matrix transformMatrix)
225	    {
226	        if (!dc.HasValidMesh) return;
227	
228	        _basicEffect!.Projection = Projection();
229	        _basicEffect.World = (dc.WorldMatrix ?? Matrix.Identity) * transformMatrix;
230	
231	        // Prefer 16-bit indices so meshes paint on the Reach profile (WebGL/BlazorGL), which
232	        // rejects 32-bit indices. Procedural meshes are tiny, so this is the path taken; only a
233	        // mesh exceeding the 16-bit vertex ceiling falls back to 32-bit indices (HiDef only).
234	        // See DrawComponent.Get16BitIndices() and the "Mesh indices render 16-bit" premise.
235	        var indices16 = dc.Get16BitIndices();
236	        var primitiveCount = dc.GetPrimitiveCount();
237	
238	        foreach (var pass in _basicEffect.CurrentTechnique.Passes)
239	        {
240	            pass.Apply();
241	            if (indices16 != null)
242	                graphicsDevice.DrawUserIndexedPrimitives(
243	                    dc.PrimitiveType, dc.Vertices, 0, dc.Vertices!.Length, indices16, 0, primitiveCount);
244	            else
245	                graphicsDevice.DrawUserIndexedPrimitives(
246	                    dc.PrimitiveType, dc.Vertices, 0, dc.Vertices!.Length, dc.Indices, 0, primitiveCount);
247	        }
248	    }
249	
250	    /// <summary>
251	    /// The scale passed to <c>SpriteBatch.Draw</c> for a sprite <see cref="DrawComponent"/>.
252	    /// A source-rect sprite maps its source pixels onto <see cref="DrawComponent.Size"/> (the
253	    /// sub-pixel-precise source→dest fit) AND honors <see cref="DrawComponent.Scale"/> — the
254	    /// entity's <c>Transform.WorldScale</c>, written by <c>SpritePrepSystem</c> — composed as
255	    /// <c>(Size / source) · Scale</c>. Composing (rather than discarding <c>Scale</c> whenever a
256	    /// source rect exists — the pre-fix behavior that never scaled placed props) is what makes a
257	    /// gizmo/world-scaled sprite's drawn quad match its hit-test quad
258	    /// (<c>GizmoTransform.SpriteWorldQuad</c>, which uses the same <c>WorldScale · (Size / source)</c>
259	    /// product). With no source rect the size-fit is undefined, so the raw
260	    /// <see cref="DrawComponent.Scale"/> applies (nine-patch / pre-sized-texture path).
261	    /// <para>
262	    /// Because <see cref="DrawComponent.Scale"/> defaults to <see cref="Vector2.One"/> and only
263	    /// <c>SpritePrepSystem</c> ever writes a non-unit value (from <c>WorldScale</c>), the composition
264	    /// is byte-identical to the pre-fix result for every unscaled sprite — including entities that set
265	    /// <see cref="DrawComponent.Size"/> deliberately and never touch <c>Scale</c> (the palette
266	    /// thumbnail, the textured cursor), which therefore never double-scale. Audit (pre-mortem #1): NO
267	    /// call site pre-bakes <c>WorldScale</c> into <c>Size</c> — every writer sets <c>Size</c> to a
268	    /// source/destination pixel size independent of the transform scale.
269	    /// </para>
270	    /// </summary>
271	    internal static Vector2 ComputeSpriteScale(DrawComponent element)
272	    {
273	        if (element.SourceRectangle is { Width: > 0, Height: > 0 } source)
274	            return new Vector2(element.Size.X / source.Width, element.Size.Y / source.Height) * element.Scale;
275	        return element.Scale;
276	    }
277	
278	    /// <summary>
279	    /// The <see cref="SpriteEffects"/> passed to <c>SpriteBatch.Draw</c> for a sprite
280	    /// <see cref="DrawComponent"/>: the OR of its two mirror flags (written by
281	    /// <c>SpritePrepSystem</c> from <c>SpriteInfoComponent.FlipHorizontally</c> /
282	    /// <c>FlipVertically</c>). Both default to <c>false</c>, so the defaults compose to
283	    /// <see cref="SpriteEffects.None"/> and an unflagged sprite renders byte-identical to before
284	    /// the flags existed.
285	    /// <para>
286	    /// The flip mirrors the pixels INSIDE the destination rect, so the drawn quad — and therefore
287	    /// the gizmo hit-test quad (<c>GizmoTransform.SpriteWorldQuad</c>) — is unchanged; a flip never
288	    /// moves what you grab. And flips compose freely with rotation and origin, because
289	    /// <c>SpriteBatch</c> applies the effect to the source sampling, not to the transform.
290	    /// </para>
291	    /// </summary>
292	    internal static SpriteEffects ComputeSpriteEffects(DrawComponent element) =>
293	        (element.FlipHorizontally ? SpriteEffects.FlipHorizontally : SpriteEffects.None) |
294	        (element.FlipVertically ? SpriteEffects.FlipVertically : SpriteEffects.None);
295	
296	    private void DrawElement(DrawComponent element)
297	    {
298	        switch (element.Type)
299	        {
300	            case DrawElementType.Sprite:
301	                if (element.Texture == null) return;
302	
303	                spriteBatch.Draw(
304	                    element.Texture,
305	                    element.Position,  // Vector2 preserves sub-pixel precision
306	                    element.SourceRectangle,
307	                    element.Color,
308	                    element.Rotation,
309	                    element.Origin,
310	                    ComputeSpriteScale(element),
311	                    ComputeSpriteEffects(element),
312	                    element.LayerDepth);
313	                break;
314	
315	            case DrawElementType.Text:
316	                if (element.Font == null || element.Text == null) return;
317	
318	                // Lay out multi-line text ourselves: one DrawString per '\n'-separated line,
319	                // advancing by the (scaled) font line height × LineSpacing. This gives a
320	                // configurable, scale-correct leading instead of relying on the font backend's
321	                // internal newline advance (which ignores the draw scale and overlaps lines).
322	                var lineSpacing = element.LineSpacing > 0 ? element.LineSpacing : DynamicTextComponent.DefaultLineSpacing;
323	                var lineAdvance = element.Font.LineHeight * element.Scale.Y * lineSpacing;
324	                var lines = element.Text.Split('\n');
325	                for (var i = 0; i < lines.Length; i++)
326	                {
327	                    var linePos = element.Position + new Vector2(0f, i * lineAdvance);
328	                    spriteBatch.DrawString(
329	                        element.Font,
330	                        lines[i],
331	                        linePos,
332	                        element.Color,
333	                        element.Rotation,
334	                        element.Origin,
335	                        element.Scale,
336	                        SpriteEffects.None,
337	                        element.LayerDepth);
338	
339	                    // Underline: a thin filled bar (1×1 pixel scaled) under the line, in the text's
340	                    // own color, spanning the rendered line width, at the line's bottom. Scales with
341	                    // the text. The text color is opaque, so this honors the opaque-fill rule.
342	                    if (element.Underline && lines[i].Length > 0)
343	                    {
344	                        var lineWidth = element.Font.MeasureString(lines[i]).Width * element.Scale.X;
345	                        if (lineWidth > 0f)
346	                        {
347	                            var thickness = MathHelper.Max(1f, element.Font.LineHeight * element.Scale.Y * 0.06f);
348	                            var underlineY = linePos.Y + element.Font.LineHeight * element.Scale.Y - thickness;
349	                            spriteBatch.Draw(
350	                                Pixel(),
351	                                new Vector2(linePos.X, underlineY),
352	                                null,
353	                                element.Color,
354	                                element.Rotation,
355	                                Vector2.Zero,
356	                                new Vector2(lineWidth, thickness),
357	                                SpriteEffects.None,
358	                                element.LayerDepth);
359	                        }
360	                    }
361	                }
362	                break;
363	
364	            case DrawElementType.NinePatch:
365	                // NinePatch handled by SpritePrepSystem creating 9 sprite elements
366	                break;
367	
368	            case DrawElementType.Mesh:
369	                // Handled separately in DrawSingleMesh via RenderInterleaved
370	                break;
371	        }
372	    }
373	
374	    public void Dispose()
375	    {
376	        _basicEffect?.Dispose();
377	        _pixel?.Dispose();
378	        _drawSet?.Dispose();
379	    }
380	
381	    public bool IsEnabled { get; set; } = true;
382	}
